import { test, expect } from "@playwright/test";

const APP = process.env.GENCLASS_APP_URL ?? "http://localhost:3000";
const SCHEDULE = {"order":"seeded","seed":1,"delay":{"minMs":0,"maxMs":600},"maxHoldMs":2100};

test("/posts: the final state does not depend on response order (GenClass f1)", async ({ page }) => {
  await page.addInitScript((s) => { (window as any).__GENCLASS_SCHEDULE__ = s; }, SCHEDULE);
  await page.goto(APP + "/posts");
  expect(await page.evaluate(() => !!(window as any).__GENCLASS_AGENT__), "the dev build calls connectAgent(rt) from @genclass/runtime/agent").toBe(true);
  await page.evaluate(() => (window as any).__GENCLASS_AGENT__.whenSettled(15000));
  await page.getByRole("button", { name: "Next page", exact: true }).or(page.locator("[name=\"Next page\"], [id=\"Next page\"]")).first().click();
  await page.getByRole("button", { name: "Next page", exact: true }).or(page.locator("[name=\"Next page\"], [id=\"Next page\"]")).first().click();
  await page.getByText("Title", { exact: true }).first().click();
  await page.evaluate(() => (window as any).__GENCLASS_AGENT__.whenSettled(15000));
  const witnesses = await page.evaluate(() => (window as any).__GENCLASS_AGENT__.witnesses());
  const errors = await page.evaluate(() => (window as any).__GENCLASS_AGENT__.errors());
  const snap = await page.evaluate(() => (window as any).__GENCLASS_AGENT__.snapshot());
  void witnesses; void errors; void snap;
  expect(snap.requests["POST /api/graphql"] ?? 0, "requests sent, as with responses in request order").toBe(5);
  expect(snap.text, "the page shows what it shows with responses in request order").toContain("gamma 0 post 014");
  expect(snap.text, "the page shows what it shows with responses in request order").toContain("Draft");
  expect(snap.text, "the page shows what it shows with responses in request order").toContain("Draft");
  expect(snap.text, "the page does not show what only the failing order showed").not.toContain("epsilon 2 post 100");
  expect(snap.text, "the page does not show what only the failing order showed").not.toContain("zeta 3 post 101");
  expect(snap.text, "the page does not show what only the failing order showed").not.toContain("Published");
